/**
 * O relógio da cianobactéria — a senoide do bicho contra a do Sol.
 *
 * O puzzle pede duas coisas ao mesmo tempo, e é por isso que ele precisa de
 * cena: a AMPLITUDE (o quanto o ritmo sobe e desce) e a FASE (a que horas ele
 * sobe). Dois números soltos não dizem se o erro é de altura ou de horário — a
 * curva diz, porque a do Sol está desenhada por baixo, fixa, esperando.
 *
 * O eixo x são as 24 horas do dia, e a faixa escura é a noite (a metade do
 * ciclo solar em que a luz está abaixo de zero). Acertar é encaixar a curva azul
 * na de ouro.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** O teto do eixo vertical — um pouco acima do máximo do slider (5). */
const ESCALA = 5.6;

/** Passo de amostragem da curva, em horas. */
const PASSO = 0.15;

const funcao: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const amplitude = numeroDe(valores, 'a', 1);
    const fase = numeroDe(valores, 'fase', 0);
    const ampAlvo = numeroDe(info, 'ampAlvo', 3);
    const faseAlvo = numeroDe(info, 'faseAlvo', 90);
    const ok = info.ok === true;

    titulo(ctx, L, A, 'O ritmo interno contra o ciclo do Sol');

    // ── O quadro do gráfico ──────────────────────────────────────────────
    const x0 = L * 0.1;
    const x1 = L * 0.96;
    const yTopo = A * 0.2;
    const yBase = A * 0.82;
    const meio = (yTopo + yBase) / 2;

    const hx = (h: number): number => x0 + (h / 24) * (x1 - x0);
    const vy = (v: number): number => meio - (v / ESCALA) * ((yBase - yTopo) / 2);

    // A onda de luz, em horas: pico ao meio-dia, zero às 6 h e às 18 h.
    const luz = (h: number): number => Math.sin(((h - 6) / 24) * 2 * Math.PI);

    // A noite, sombreada: é o pano de fundo que dá sentido à fase.
    ctx.fillStyle = 'rgb(35 42 85 / 8%)';
    ctx.fillRect(x0, yTopo, hx(6) - x0, yBase - yTopo);
    ctx.fillRect(hx(18), yTopo, x1 - hx(18), yBase - yTopo);

    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    ctx.strokeRect(x0, yTopo, x1 - x0, yBase - yTopo);

    // Eixo do zero e as marcas de hora.
    ctx.strokeStyle = cor.trilho;
    ctx.beginPath();
    ctx.moveTo(x0, meio);
    ctx.lineTo(x1, meio);
    ctx.stroke();

    const miudo = limitar(A * 0.032, 8, 11);
    for (const h of [0, 6, 12, 18, 24]) {
      ctx.strokeStyle = cor.trilho;
      ctx.setLineDash([2, 4]);
      ctx.beginPath();
      ctx.moveTo(hx(h), yTopo);
      ctx.lineTo(hx(h), yBase);
      ctx.stroke();
      ctx.setLineDash([]);
      texto(ctx, `${h}h`, hx(h), yBase + miudo * 1.4, miudo, { cor: cor.fraco });
    }

    // ── A curva do Sol: o alvo, na amplitude e na fase certas ────────────
    const curva = (amp: number, faseGraus: number): void => {
      ctx.beginPath();
      for (let h = 0; h <= 24 + PASSO; h += PASSO) {
        const v = amp * Math.sin(((h - 6) / 24) * 2 * Math.PI - (faseGraus * Math.PI) / 180);
        const x = hx(Math.min(h, 24));
        const y = vy(v);
        if (h === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    };

    // A luz do dia, preenchida: só a parte positiva, que é o que ilumina.
    ctx.save();
    ctx.beginPath();
    ctx.rect(x0, yTopo, x1 - x0, meio - yTopo);
    ctx.clip();
    ctx.fillStyle = 'rgb(176 125 16 / 14%)';
    ctx.beginPath();
    ctx.moveTo(x0, meio);
    for (let h = 0; h <= 24 + PASSO; h += PASSO) {
      ctx.lineTo(hx(Math.min(h, 24)), vy(luz(h) * ESCALA));
    }
    ctx.lineTo(x1, meio);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    ctx.strokeStyle = cor.ouro;
    ctx.lineWidth = 2.4;
    ctx.setLineDash([6, 4]);
    curva(ampAlvo, faseAlvo);
    ctx.setLineDash([]);

    // ── A curva da bactéria: o que o investigador está ajustando ─────────
    ctx.strokeStyle = ok ? cor.verde : cor.azul;
    ctx.lineWidth = 3;
    ctx.lineJoin = 'round';
    curva(amplitude, fase);

    // A régua da amplitude, no pico da curva do investigador.
    const hPico = 6 + fase / 15 + 6;
    const xPico = hx(((hPico % 24) + 24) % 24);
    ctx.strokeStyle = ok ? cor.verde : cor.azul;
    ctx.lineWidth = 1.4;
    ctx.setLineDash([3, 3]);
    ctx.beginPath();
    ctx.moveTo(xPico, meio);
    ctx.lineTo(xPico, vy(amplitude));
    ctx.stroke();
    ctx.setLineDash([]);

    etiqueta(
      ctx,
      `A = ${amplitude.toFixed(1).replace('.', ',')}`,
      xPico,
      vy(amplitude) - miudo * 1.8,
      miudo,
      ok ? cor.verde : cor.azul,
      700,
    );
    // Dentro do quadro, no canto: embaixo ela caía sobre as marcas de hora.
    etiqueta(
      ctx,
      `φ = ${Math.round(fase)}°  (alvo ${Math.round(faseAlvo)}°)`,
      x0 + 6,
      yTopo + miudo * 1.5,
      miudo,
      cor.fraco,
      700,
      { alinhamento: 'left' },
    );

    // O erro que sobra guia a dica, e cada eixo tem a sua direção: dizer só
    // "ajuste" manda o investigador tatear os dois sliders.
    const erroAmplitude = amplitude - ampAlvo;
    const erroFase = fase - faseAlvo;
    const falta =
      Math.abs(erroAmplitude) > 0.2
        ? erroAmplitude < 0
          ? 'A onda é baixa demais: aumente a amplitude.'
          : 'A onda é alta demais: diminua a amplitude.'
        : erroFase < 0
          ? 'O pico chega cedo demais: aumente a fase.'
          : 'O pico chega tarde demais: diminua a fase.';

    rodape(ctx, L, A, ok, 'Ritmo em sincronia com o dia ✔', falta);
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A }) => desenhar(ctx, L, A),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default funcao;
